BEGIN;
UPDATE articulos SET metadata = '{"areas": ["creatividad", "sociabilidad"], "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "cantidad": "04 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa"], "objetivos": ["Estimular la creatividad", "Fomentar la comunicación e interpretación", "Trabajo en equipo", "Crear un ambiente de distensión"], "materiales": ["Ninguno"], "variaciones": "<b>Historia Atroz con Efectos de Sonido:</b> Una patrulla actúa mientras otra realiza la banda sonora y ruidos ambientales en vivo.<br><b>Historia Atroz en Reversa:</b> Representar la trama comenzando por el desenlace dramático hasta llegar al inicio cómico.<br><b>Edición Leyendas Nua Mana:</b> Recrear pasajes humorísticos basados en anécdotas reales del Grupo Scout.", "recomendaciones": "Mantener un ritmo fluido en la narración sin pausas prolongadas. Promover un ambiente festivo donde se valore la audacia escénica.", "justificacion_areas": "La Drama-Comedia de la Historia Atroz potencia la creatividad al exigir la improvisación inmediata de roles dramáticos, gestos cómicos y expresión corporal. Desarrolla la sociabilidad al afianzar la desinhibición social, el juego cooperativo sin juicio y el espíritu festivo en la unidad.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Participando con alegría y soltura en la dramatización cómica del cuento narrado."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando emociones y caracterizaciones teatrales exageradas ante la unidad."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Improvisando escenas dramáticas y personajes cómicos al ritmo de la historia."}, {"id": "0136350b-c2b2-429f-8feb-2fdc57e29b8b", "area": "Creatividad", "unidad": "Compañía", "texto": "Me gusta cantar y conozco muchas canciones.", "como_se_cumple": "Aportando expresiones vocales, efectos sonoros y canciones en la actuación de patrulla."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Desarrollando audacia escénica y actuación colectiva en la Tropa."}, {"id": "0136350b-c2b2-429f-8feb-2fdc57e29b8b", "area": "Creatividad", "unidad": "Tropa", "texto": "Me gusta cantar y conozco muchas canciones.", "como_se_cumple": "Creando ambientaciones cómicas y expresiones líricas durante la dramatización."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "unidad": "Manada", "como_se_cumple": "Acatando los roles asignados en el relato sin vacilaciones."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "unidad": "Manada", "como_se_cumple": "Participando con alegría y respeto en las representaciones grupales."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Compañía", "como_se_cumple": "Construyendo un clima libre de burlas que incentive la participación de todas."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Compañía", "como_se_cumple": "Apoyando con aplausos el desempeño escénico de las compañeras de unidad."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Tropa", "como_se_cumple": "Fomentando el compañerismo y la confianza mutua en presentaciones de fogata."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Tropa", "como_se_cumple": "Afianzando la cohesión e integración entre las distintas patrullas."}]}'::jsonb WHERE slug = 'la-drama-comedia-de-la-historia-atroz';
DELETE FROM articulo_objetivos_educativos WHERE articulo_id = (SELECT id FROM articulos WHERE slug = 'la-drama-comedia-de-la-historia-atroz');
